const j=$input.first().json, e=j.execution||{}, w=j.workflow||{};
const message=String(e.error?.message || j.trigger?.error?.message || '');
const match=message.match(/OPTIMA ([A-Z0-9_]+)(?: order=([A-Za-z0-9_-]{1,200}) stage=([A-Za-z]+))?/);
const safe=(v)=>typeof v==='string' && /^[A-Za-z0-9 _.-]{1,100}$/.test(v)?v:'unavailable';
const executionId=safe(e.id), reason=match?match[1]:'UNEXPECTED_EXECUTION_FAILURE';
// Reconstruct the local execution link; never forward an arbitrary error URL.
const workflowId=safe(w.id);
const url=executionId==='unavailable' || workflowId==='unavailable'?'unavailable':'http://localhost:5678/workflow/'+encodeURIComponent(workflowId)+'/executions/'+encodeURIComponent(executionId);
const text=[`Workflow: ${safe(w.name)}`,`Order: ${match?.[2]||'unavailable'}`,`Failure timestamp: ${new Date().toISOString()}`,`Failed node: ${safe(e.lastNodeExecuted)}`,`Reason: ${reason}`,`Stage: ${match?.[3]||'unavailable'}`,`Execution ID: ${executionId}`,`Execution URL: ${url}`,'Action: Check credential assignment, token scopes, PHP confirmation, unique property and pipeline/stage. For 429/5xx wait then resend the SAME signed order; the unique Deal key reconciles uncertain creates.'].join('\n');
return [{json:{subject:'Optima HubSpot sync failure: '+reason,text}}];
